// "The world the year you were born" — the Wikipedia/Wikidata half of the
// Family Birthday page (the date maths is lib/birthday.ts).
//
// Reads src/data/birthYears.json, BUNDLED with the app and generated by
// scripts/build-birth-years.py (see its header for sources and ranking). It
// used to be a live per-DAY Wikipedia query; the user preferred the birth
// YEAR, and the year-level queries are far too slow to run on open (24 s for
// people, a timeout for events), so they're precomputed instead. Upshot: the
// page is instant, works offline, and nothing about the user leaves the phone.
//
// Event text is Wikipedia's (CC BY-SA) — the page must keep its credit line;
// people data is Wikidata's (CC0).

export type YearPerson = {
  name: string
  desc: string | null
  url: string | null
  photo: string | null
}

export type YearEvent = {
  text: string
  url: string | null
  /** Free (Commons) thumbnail of the event's article, or of a person/place
   *  it names when the event has none — never a fair-use image. */
  photo: string | null
}

type L3 = Partial<Record<'en' | 'es' | 'pt', string | null>>
type RawYear = {
  p: { q: string; n: L3; d: L3; w: L3; i: string | null; f: number }[]
  e: Partial<Record<'en' | 'es' | 'pt', { t: string; u: string | null; i?: string | null }[]>>
}

let data: Record<string, RawYear> | null = null
function load(): Record<string, RawYear> {
  // Required lazily: ~1 MB of JSON only gets parsed when someone actually
  // opens a Birthday page, not at app start.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  if (!data) data = require('../data/birthYears.json') as Record<string, RawYear>
  return data
}

const pick = (m: L3, lang: string): string | null =>
  (m as Record<string, string | null | undefined>)[lang] ?? m.en ?? m.es ?? m.pt ?? null

/** Famous people born in `year` (most famous first) and the year's main
 *  events (calendar order), in `lang` — falling back to English for a person
 *  or a year that language's wiki doesn't cover. */
export function birthYearFacts(year: number, lang: string): { people: YearPerson[]; events: YearEvent[] } {
  const y = load()[String(year)]
  if (!y) return { people: [], events: [] }
  const people = y.p
    .map((p) => {
      const name = pick(p.n, lang)
      if (!name) return null
      const title = (p.w as Record<string, string | null | undefined>)[lang] ? lang : p.w.en ? 'en' : null
      const article = title ? (p.w as Record<string, string>)[title] : null
      return {
        name,
        desc: pick(p.d, lang),
        url: article ? `https://${title}.m.wikipedia.org/wiki/${encodeURIComponent(article.replace(/ /g, '_'))}` : null,
        photo: p.i,
      }
    })
    .filter((p): p is YearPerson => !!p)
  const evs = y.e[lang as 'en'] ?? y.e.en ?? []
  return { people, events: evs.map((e) => ({ text: e.t, url: e.u, photo: e.i ?? null })) }
}
